import React from 'react';
import { Filter, HierarchySelectorItem } from './types';
export type HierarchySelectorProps = {
    /**
     * An array of nodes
     */
    data: HierarchySelectorItem[];
    /**
     * Max number of levels
     *
     * @default 5
     */
    maxLevels?: number;
    /**
     * Initial selection
     */
    selections: Filter[];
    /**
     * On change handler
     */
    onSelectionChange: (selection: Filter[]) => void;
    /**
     * noRollup
     *
     * @default false
     */
    noRollup?: boolean;
    /**
     * Header strings
     */
    levelMetaData: {
        label: string;
    }[];
    /**
     * To disable the selector
     *
     * @default false
     */
    disabled?: boolean;
    /**
     * To make the selector as single select
     */
    singleSelect?: boolean;
};
/**
 * Hierarchy selector is used to display a tree of nodes where the user may select multiple options, including all or none.
 *
 * ### Content
 *
 * #### Data
 *
 * Data should be structured in the type HierarchySelectorItem[]
 *
 * ### Features
 *
 * #### Max Levels
 *
 * Default - 5
 *
 * Can optionally change the number of levels by passing in the `maxLevels` prop
 *
 * #### Selections
 *
 * Passing the array here in the type Filter format pre selects the data in the hierarchy
 *
 * #### Disabled
 *
 * Can optionally disable the view of selector. Works alongside selections to disable checkboxes
 *
 * #### Single select
 *
 * Make the selector as single select and should be used along with `noRollup` prop set as true to make it truly single select
 *
 * ### Interaction
 *
 * The Hierarchy Selector requires a callback to be provided to the `onSelectionChange` prop to handle interaction with checkboxes within the selector.
 *
 * ### Example
 *
 * ```tsx
 * export default () => {
 * const [hierarchySelections, setHierarchySelections] = useState<Filter[]>([]);
 * const maxLevels = 5;
 *
 * const levelMetaData = [
 *   { label: 'SBUs' },
 *   { label: 'Departments' },
 *   { label: 'Category Groups' },
 *   { label: 'Categories' },
 *   { label: 'Sub Categories' },
 * ];
 *
 * const updateHierarchySelections = (hierarchySelections) => {}
 *
 * return (
 *  <div>
 *      <HierarchySelector
 *      data={data}
 *      maxLevels={maxLevels}
 *      onSelectionChange={updateHierarchySelections}
 *      selections={hierarchySelections}
 *      noRollup={false}
 *      levelMetaData={levelMetaData}
 *      disabled={false}
 *      />
 *  </div>
 * );
 * };
 * ```
 *
 */
export declare const HierarchySelector: React.FC<HierarchySelectorProps>;
